float drawLine(vec2 uv, vec2 a, vec2 b, float width) {
    vec2 pa = uv - a;
    vec2 ba = b - a;
    float h = clamp(dot(pa, ba) / dot(ba, ba), 0.0, 1.0);
    float d = length(pa - ba * h);
    return smoothstep(width, 0.0, d);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // Normalize coordinates
    vec2 uv = (2.0 * fragCoord - iResolution.xy) / min(iResolution.x, iResolution.y);

    // Pure white background
    vec3 col = vec3(1.0);

    // Thin, precise axes
    float axisWidth = 0.0015;
    col = mix(col, vec3(0.0), smoothstep(axisWidth, 0.0, abs(uv.x)));
    col = mix(col, vec3(0.0), smoothstep(axisWidth, 0.0, abs(uv.y)));

    // Unit circle - thin and precise
    float dist = length(uv);
    col = mix(col, vec3(0.0), smoothstep(0.002, 0.0, abs(dist - 1.0)));

    // Calculate angle
    float angle = iTime * 0.5;

    // Define points
    vec2 point = vec2(cos(angle), sin(angle));
    vec2 samePoint = vec2(-cos(angle), sin(angle));

    // Draw minimal radial lines
    float lineWidth = 0.0015;
    col = mix(col, vec3(0.0), drawLine(uv, vec2(0.0), point, lineWidth));
    col = mix(col, vec3(0.0), drawLine(uv, vec2(0.0), samePoint, lineWidth));

    // Draw minimal projection lines
    col = mix(col, vec3(0.0), drawLine(uv, point, vec2(cos(angle), 0.0), lineWidth));
    col = mix(col, vec3(0.0), drawLine(uv, point, vec2(0.0, sin(angle)), lineWidth));
    col = mix(col, vec3(0.0), drawLine(uv, samePoint, vec2(-cos(angle), 0.0), lineWidth));
    col = mix(col, vec3(0.0), drawLine(uv, samePoint, vec2(0.0, sin(angle)), lineWidth));

    // Small, precise points
    float pointSize = 0.01;
    col = mix(col, vec3(0.0), smoothstep(pointSize, 0.0, length(uv - point)));
    col = mix(col, vec3(0.0), smoothstep(pointSize, 0.0, length(uv - samePoint)));

    fragColor = vec4(col, 1.0);
}
